sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;

  (function ($scope) {
  $scope.slaData = null;

  function calculateSLA(priority, createdDate) {
    const now = new Date();
    const created = new Date(createdDate);
    let slaHours = 0;

    if (priority === 'High') slaHours = 48;
    else if (priority === 'Medium') slaHours = 96;
    else slaHours = 168;

    const due = new Date(created.getTime() + slaHours * 3600000);
    const diffMs = due - now;
    const diffHrs = Math.floor(diffMs / 3600000);
    const diffMins = Math.floor((diffMs % 3600000) / 60000);
    const timeUsedMs = now - created;
    const percentageUsed = Math.min(100, (timeUsedMs / (slaHours * 3600000)) * 100);

    let status = '';
    let color = 'green';

    if (diffMs > 86400000) {
      status = 'healthy';
      color = 'green';
    } else if (diffMs > 0) {
      status = 'near breach';
      color = 'yellow';
    } else {
      status = 'breached';
      color = 'red';
    }

    return {
      due: due.toLocaleString(),
      remaining: diffMs > 0 ? `${diffHrs}h ${diffMins}m remaining` : `Overdue by ${Math.abs(diffHrs)}h ${Math.abs(diffMins)}m`,
      color: color,
      percentageUsed: percentageUsed,
      status: status
    };
  }

  if ($scope.data.complaint && $scope.data.complaint.sys_id) {
    $scope.slaData = calculateSLA($scope.data.complaint.priority, $scope.data.complaint.created);
  }
});
};

sp_widget.css:
.progress {
  height: 20px;
