sp_widget.script:
(function() {
  var complaint = {};
  var user = gs.getUserID();
  var gr = new GlideRecord('x_1777185_home_s_0_complaint_details'); 

  gr.addQuery('opened_by', user); // assuming 'opened_by' references the requester
  gr.addQuery('current_status', 'NOT IN', 'Resolved,Rejected,Cancelled'); // filter active
  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);

  if (gr.query() && gr.next()) {
    complaint = {
      sys_id: gr.getValue('sys_id'),
      created: gr.getValue('sys_created_on'),
      priority: gr.getValue('case_priority'), // High, Medium, Low
      status: gr.getValue('current_status')
    };
  }

  return {
    complaint: complaint
  };
})();
